  noLoop();
}

// Draw Background
function draw() {
  // Create background gradient
  let R = new Random();
  let S = new Random();
  let T = new Random();
  let fromColor = color(255, S.random_int(0,255), 255);
  let toColor = color(255, R.random_int(0,255), T.random_int(0,255));
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(fromColor, toColor, inter);
    stroke(c);
    line(0, y, width, y);
  }
  
  // Add geometric shapes
  noFill();
  stroke(S.random_int(0,255));
  strokeWeight(R.random_int(5,14));
  let A = new Random();
  let B = new Random();
  let C = new Random();
  let W = new Random();
  let H = new Random();
  let X = new Random();
  let Y = new Random();
  let numShapes = A.random_int(4, 50);
  for (let i = 0; i < numShapes; i++) {
    let shapeType = C.random_int(0,2); // 0: ellipse, 1: rect, 2: triangle
    let size = B.random_int(10,100);
    let x = X.random_int(1,900);
    let y = Y.random_int(1,1600); 
    switch (shapeType) {
      case 0:
        ellipse(W.random_int(1,1800), H.random_int(1,3200), B.random_int(100,1800), B.random_int(10,3200));
        break;
      case 1:
        rect(W.random_int(1,1800), H.random_int(1,3200), B.random_int(10,1800), B.random_int(10,3200));
        break;
      case 2:
        let x1 = W.random_int(1,1800) - size / 2;
        let x2 = W.random_int(1,1800) + size / 2;
        let y1 = y + H.random_int(1,3200) / 2 * sqrt(3);
        let y2 = y + H.random_int(1,3200) / 2 * sqrt(3);
        let x3 = W.random_int(1,1800);
        let y3 = y - H.random_int(1,3200) * sqrt(3) / 2;
        triangle(x1, y1, x2, y2, x3, y3);
        break;
    }
  }
}
